<?php
/**  * Verify database state and clean up any issues  */  require_once __DIR__ . '/../public/db_connect.php';  try {  echo "=== Database Verification Tool ===\n\n";  // 1. Check current database  $dbName = $pdo->query("SELECT DATABASE()")->fetchColumn();  echo "Connected to database: {$dbName}\n\n";  // 2. Check if pending_price_approvals table exists  $tableExists = $pdo->query("SHOW TABLES LIKE 'pending_price_approvals'")->fetch();  if (!$tableExists) {  echo "ERROR: Table 'pending_price_approvals' does not exist!\n";  exit(1);  }  echo " Table 'pending_price_approvals' exists\n\n";  // 3. Check for foreign key constraints  echo "Checking foreign key constraints:\n";  $fks = $pdo->query("  SELECT  CONSTRAINT_NAME,  COLUMN_NAME,  REFERENCED_TABLE_NAME,  REFERENCED_COLUMN_NAME  FROM information_schema.KEY_COLUMN_USAGE  WHERE TABLE_SCHEMA = DATABASE()  AND TABLE_NAME = 'pending_price_approvals'  AND REFERENCED_TABLE_NAME IS NOT NULL  ")->fetchAll(PDO::FETCH_ASSOC);  if (empty($fks)) {  echo "  No foreign key constraints found.\n\n";  } else {  foreach ($fks as $fk) {  echo "  - {$fk['CONSTRAINT_NAME']}: {$fk['COLUMN_NAME']} -> {$fk['REFERENCED_TABLE_NAME']}.{$fk['REFERENCED_COLUMN_NAME']}\n";  // If product_id has FK, remove it  if ($fk['COLUMN_NAME'] === 'product_id') {  echo "  WARNING: Found FK on product_id. Removing...\n";  $pdo->exec("ALTER TABLE pending_price_approvals DROP FOREIGN KEY {$fk['CONSTRAINT_NAME']}");  echo "  Removed {$fk['CONSTRAINT_NAME']}\n";  }  }  echo "\n";  }  // 4. Check for orphaned pending records  echo "Checking for orphaned pending records:\n";  // Check fuel_inventory references  $orphanedFuel = $pdo->query("  SELECT p.id, p.product_id, p.product_type  FROM pending_price_approvals p  LEFT JOIN fuel_inventory f ON p.product_id = f.id  WHERE p.product_type IN ('fuel', 'fuel_inventory')  AND f.id IS NULL  AND p.status = 'pending'  ")->fetchAll(PDO::FETCH_ASSOC);  if (!empty($orphanedFuel)) {  echo "  Found " . count($orphanedFuel) . " orphaned fuel records:\n";  foreach ($orphanedFuel as $record) {  echo "  - ID: {$record['id']}, product_id: {$record['product_id']}, type: {$record['product_type']}\n";  }  // Clean them up  $ids = array_column($orphanedFuel, 'id');  $placeholders = implode(',', array_fill(0, count($ids), '?'));  $pdo->prepare("DELETE FROM pending_price_approvals WHERE id IN ($placeholders)")  ->execute($ids);  echo "  Cleaned up orphaned fuel records\n\n";  } else {  echo "  No orphaned fuel records\n\n";  }  // Check merchandise references  $orphanedMerch = $pdo->query("  SELECT p.id, p.product_id  FROM pending_price_approvals p  LEFT JOIN inventory_products i ON p.product_id = i.id  WHERE p.product_type = 'merchandise'  AND i.id IS NULL  AND p.status = 'pending'  ")->fetchAll(PDO::FETCH_ASSOC);  if (!empty($orphanedMerch)) {  echo "  Found " . count($orphanedMerch) . " orphaned merchandise records:\n";  foreach ($orphanedMerch as $record) {  echo "  - ID: {$record['id']}, product_id: {$record['product_id']}\n";  }  $ids = array_column($orphanedMerch, 'id');  $placeholders = implode(',', array_fill(0, count($ids), '?'));  $pdo->prepare("DELETE FROM pending_price_approvals WHERE id IN ($placeholders)")  ->execute($ids);  echo "  Cleaned up orphaned merchandise records\n\n";  } else {  echo "  No orphaned merchandise records\n\n";  }  // Check service_type references  $orphanedService = $pdo->query("  SELECT p.id, p.product_id  FROM pending_price_approvals p  LEFT JOIN job_order_service_types s ON p.product_id = s.id  WHERE p.product_type = 'service_type'  AND s.id IS NULL  AND p.status = 'pending'  ")->fetchAll(PDO::FETCH_ASSOC);  if (!empty($orphanedService)) {  echo "  Found " . count($orphanedService) . " orphaned service records:\n";  foreach ($orphanedService as $record) {  echo "  - ID: {$record['id']}, product_id: {$record['product_id']}\n";  }  $ids = array_column($orphanedService, 'id');  $placeholders = implode(',', array_fill(0, count($ids), '?'));  $pdo->prepare("DELETE FROM pending_price_approvals WHERE id IN ($placeholders)")  ->execute($ids);  echo "  Cleaned up orphaned service records\n\n";  } else {  echo "  No orphaned service records\n\n";  }  // 5. Show current pending approvals  echo "Current pending approvals:\n";  $pending = $pdo->query("  SELECT id, station_id, product_type, product_id, old_price, new_price, status, created_at  FROM pending_price_approvals  WHERE status = 'pending'  ORDER BY created_at DESC  LIMIT 10  ")->fetchAll(PDO::FETCH_ASSOC);  if (empty($pending)) {  echo "  No pending approvals\n\n";  } else {  echo "  Found " . count($pending) . " pending approval(s):\n";  foreach ($pending as $p) {  echo "  - ID: {$p['id']}, Type: {$p['product_type']}, Product ID: {$p['product_id']}, ";  echo "Price: ₱{$p['old_price']} → ₱{$p['new_price']}, Created: {$p['created_at']}\n";  }  echo "\n";  }  // 6. Final table structure  echo "Final table structure:\n";  $result = $pdo->query("SHOW CREATE TABLE pending_price_approvals");  $row = $result->fetch(PDO::FETCH_ASSOC);  echo $row['Create Table'] . "\n\n";  echo " Verification and cleanup completed successfully!\n";  echo "\nYou can now try to save your changes again.\n";  } catch (PDOException $e) {  echo "ERROR: " . $e->getMessage() . "\n";  exit(1);
}
